'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright');
const root=process.env.FORUM_CONFIRMATIONS_ASSET_DIR||path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8');
function fn(s,name){let a=s.indexOf('function '+name+'(');assert.ok(a>=0,name);if(s.slice(a-6,a)==='async ')a-=6;return s.slice(a,s.indexOf('\n}',a)+2);}
test('confirmations : suppressions réelles simulées, 54 bascules, neuf langues et 320/390/1280 sans nouvelle action',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:780}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><body class="plateau-body"><input id="draft" value="Brouillon <inchangé>"><div id="modal-postes" class="open"></div><div id="forum-main"></div><div id="result-toast"><div id="toast-result" class="toast-result"></div><div id="toast-sub" class="toast-sub"></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});
 await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.calls=[];window.incidents=[];window.noterIncidentSession=(...a)=>incidents.push(a);window.state={pa:20,arg:300,progression:{stage:2}};window.currentForumId='general';window.FORUM_TOPICS={};window.sbDelete=async(...a)=>calls.push(['delete',...a]);window.sbUpdate=async(...a)=>calls.push(['update',...a]);window.backToList=()=>calls.push(['back']);window.renderForumContent=()=>'<p>Liste conservée</p>';window.fetch=()=>{throw Error('Réseau réel interdit');};window.snap=()=>JSON.stringify({state,calls,incidents,topics:FORUM_TOPICS,content:document.getElementById('forum-main').innerHTML,closed:!document.getElementById('modal-postes').classList.contains('open'),draft:document.getElementById('draft').value,focus:document.activeElement.id,selection:document.getElementById('draft').selectionStart,timer:window._toastTimer});});
 for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/toast-resources.js','i18n/forum-feedback-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:fn(read('plateau-core.js'),'showToast')+'\n'+fn(read('forum.js'),'executerSuppressionPost')});
 for(const first of [true,false]){await page.evaluate(async first=>{await i18next.changeLanguage('fr');calls.length=0;FORUM_TOPICS.general=[{id:'topic',replies:1,posts:[{id:'a',body:'Texte libre <inchangé>'},{id:'b',body:'Autre texte'}]}];document.getElementById('modal-postes').classList.add('open');document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,5);await executerSuppressionPost('topic',first?'a':'b');window.before=snap();},first);
 const key=first?'titleTopicDeleted':'titleMessageDeleted';for(const lang of ['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de']){const got=await page.evaluate(async({lang,key})=>{await i18next.changeLanguage(lang);return {same:snap()===before,title:document.getElementById('toast-result').textContent,expected:i18next.t('forumFeedback.'+key),body:document.getElementById('toast-sub').innerHTML,dir:document.querySelector('#toast-result [data-i18n]')?.dir,overflow:document.documentElement.scrollWidth>innerWidth};},{lang,key});assert.equal(got.same,true);assert.equal(got.title,got.expected);assert.equal(got.body,'');assert.equal(got.dir,lang==='ar'?'rtl':'');assert.equal(got.overflow,false);}}
 assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
